def word_count(text):
    counts = {}
    for w in text.split():
        # Remove leading and trailing punctuation
        w = ''.join(c for c in w if c.isalnum())
        # Convert to lowercase
        w = w.lower()
        counts[w] = counts.get(w, 0) + 1
    return counts

