def caesar(s, k):
    result = []
    for char in s:
        if char.isalpha():
            # Find the position of the character in the alphabet
            base = ord('A') if char.isupper() else ord('a')
            # Calculate the new position
            new_pos = (ord(char) - base + k) % 26 + base
            # Convert back to a character
            result.append(chr(new_pos))
        else:
            result.append(char)
    return ''.join(result)

def caesar(s, k):
    result = []
    for char in s:
        if char.isalpha():
            # Determine the base (A for uppercase, a for lowercase)
            base = ord(char) - ord('A') if char.isupper() else ord(char) - ord('a')
            # Shift the character
            shifted = (base + k) % 26
            # Convert back to the corresponding character
            result.append(chr(shifted + ord('A') if char.isupper() else shifted + ord('a')))
        else:
            result.append(char)
    return ''.join(result)

